styles.css.after:
@media(max-width:900px){.analysis-columns{grid-template-columns:minmax(0,1fr);gap:0}.investigation .analysis-card{padding:18px}}

/* Overview insights retain their capture time as replay continues. */
.insight-card{margin:24px 0 20px;padding:24px;background:var(--light);border:1px solid var(--line)}
.insight-card .card-head{align-items:center;flex-wrap:wrap}.insight-card .card-head>div{flex:1;min-width:220px}
.insight-card .insight-subtitle{margin:6px 0 0;font-size:14px;color:var(--mut);line-height:1.5}
.insight-card .analysis-meta{margin:14px 0 0;font-size:12px}.insight-card .analysis-footnote{border-top:1px solid var(--line);padding-top:14px;margin:18px 0 0;font-size:12px}
.insight-empty{padding:18px 0 4px;color:var(--mut);max-width:820px}.insight-findings{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px 28px;margin-top:20px}
.insight-findings h3{font-size:16px;margin:0}.insight-findings p{margin:8px 0}.insight-metrics{display:flex;flex-wrap:wrap;gap:6px}
.insight-metric{font-size:12px;line-height:1.5;padding:4px 8px;border:1px solid var(--line);border-radius:6px;color:var(--mut)}
.insight-focus{margin-top:24px}.insight-focus h3{font-size:16px;margin:0 0 8px}.insight-case{display:flex;align-items:baseline;gap:12px;padding:10px 0;border-top:1px solid var(--line)}.insight-case p{margin:0}.insight-case button{flex-shrink:0}
.insight-stale{border-left:3px solid var(--mid);padding-left:12px;font-size:13px;color:var(--mut)}
@media(max-width:900px){.insight-findings{grid-template-columns:1fr}.insight-card{padding:20px}.insight-case{flex-wrap:wrap;gap:6px}}

styles.css.before:
@media(max-width:1100px){
  .investigation .detail-grid{grid-template-columns:minmax(0,1fr)}
  .investigation .detail-grid>.account-card{min-height:0}
  .investigation .case-bar{align-items:stretch;flex-direction:column}
  .investigation .case-actions{margin-left:0}
  .investigation .expanded-info{grid-template-columns:repeat(2,minmax(0,1fr))}
}

.review-dialog{border:1px solid var(--line);border-radius:18px;background:#F7F2EB;color:#081F5C;padding:28px;width:min(520px,calc(100vw - 40px));max-height:85vh;overflow:auto;box-sizing:border-box}
.review-dialog::backdrop{background:rgba(8,31,92,.45)}
.review-dialog h2{margin:0 0 12px}.review-dialog label{display:grid;gap:8px;margin:20px 0;font-size:15px}
.review-dialog textarea,.review-dialog select{box-sizing:border-box;width:100%;padding:12px;border:1px solid #7096D1;border-radius:8px;background:#fff;color:#081F5C;font:inherit}
.review-dialog textarea{resize:vertical}.review-actions{display:flex;justify-content:flex-end;gap:12px;margin-top:24px}.review-error{color:#9c2929}.review-summary{padding:20px;margin-bottom:20px}.review-summary h2{font-size:16px;margin:0 0 12px}.review-summary p{white-space:pre-wrap;overflow-wrap:anywhere}.review-dialog button:disabled{opacity:.55;cursor:wait}

