/* Evidence-bound AI review uses the existing dashboard palette. */
.investigation .analysis-card{margin-top:24px;padding:24px;border:1px solid var(--line);background:var(--light)}
.analysis-meta,.analysis-muted,.analysis-footnote{color:var(--mut)}
.analysis-meta{font-size:13px;overflow-wrap:anywhere}.analysis-card p{margin:12px 0;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}
.analysis-conclusion{margin-top:20px}.analysis-verdict{display:inline-block;font-size:18px;font-weight:650;border-left:3px solid var(--ink);padding-left:12px}
.analysis-columns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
.analysis-section{min-width:0;padding-top:20px}.analysis-section h3{font-size:15px;font-weight:650;margin:0 0 10px}.analysis-section ul{padding-left:20px;margin:10px 0}.analysis-section li{line-height:1.7;margin:8px 0;overflow-wrap:anywhere;white-space:pre-wrap}
.analysis-finding{margin-bottom:18px}.analysis-refs{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.analysis-reference{border:1px solid var(--ink);background:transparent;color:var(--ink);border-radius:5px;font:inherit;font-size:13px;padding:4px 9px;cursor:pointer}.analysis-reference:hover,.analysis-reference:focus-visible{background:var(--ink);color:var(--paper)}.analysis-feature{font-size:12px;color:var(--mut);overflow-wrap:anywhere}
.analysis-pattern{border-top:1px solid var(--line);margin-top:10px}.analysis-footnote{font-size:13px;border-top:1px solid var(--line);padding-top:14px;margin-bottom:0!important}
.analysis-notice,.analysis-error{border-left:3px solid var(--ink);padding:8px 12px;background:var(--paper)}
.analysis-progress{display:flex;align-items:center;gap:12px}.analysis-dot{display:inline-block;flex:0 0 8px;height:8px;border-radius:50%;background:var(--ink);animation:analysis-pulse 1.4s ease-in-out infinite}@keyframes analysis-pulse{50%{opacity:.3}}
